import { readFileSync } from 'node:fs';
import { test as base } from '@playwright/test';
import { API_HOST } from '../playwright.config.js';

// fixtures/api/*.json generated by `python manage.py export_e2e_fixtures`
export const loadFixture = (name) =>
  JSON.parse(readFileSync(new URL(`./fixtures/api/${name}.json`, import.meta.url)));

export const FIXTURE_NOW = new Date(loadFixture('meta').now);

const PIXEL_PNG = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=',
  'base64',
);

const defaultResponses = () => ({
  '/api/session': {},  // signed out
  '/api/webcams/': loadFixture('webcams'),
  '/api/cms/advisories/': [],
  '/api/cms/bulletins/': [],
  '/api/cms/emergency-alert/': [],
  '/api/areas/': [],
});

const isLocal = (url) => ['localhost', '127.0.0.1'].includes(url.hostname);

export const test = base.extend({
  api: [async ({ page }, use, testInfo) => {
    const responses = Object.fromEntries(
      Object.entries(defaultResponses()).map(([path, json]) => [path, { status: 200, json }]),
    );
    const unhandled = new Set();

    await page.clock.setFixedTime(FIXTURE_NOW);

    // no real network: API from fixtures, everything else off-host aborted
    await page.route((url) => !isLocal(url), (route) => {
      const url = new URL(route.request().url());
      if (url.origin !== API_HOST) {
        return route.abort();
      }

      if (url.pathname.startsWith('/images/')) {
        return route.fulfill({ contentType: 'image/png', body: PIXEL_PNG });
      }

      const response = responses[url.pathname];
      if (!response) {
        unhandled.add(url.pathname);
        return route.fulfill({ json: [] });
      }

      return route.fulfill(response);
    });

    await use({
      respond: (path, json, status = 200) => { responses[path] = { status, json }; },
    });

    if (unhandled.size) {
      testInfo.annotations.push({ type: 'unmocked API', description: [...unhandled].join(', ') });
    }
  }, { auto: true }],
});

export { expect } from '@playwright/test';
